-- =============================================================================
-- BI Rationalization & Migration Workbench — Migration Copilot reference corpus
-- Practitioner reference documents retrieved by Cortex Search to answer "why"
-- questions. Each document starts with its DOC_ID so exact-id lookups hit.
-- =============================================================================
USE DATABASE BI_MODERNIZATION;
USE SCHEMA AI;

CREATE OR REPLACE TABLE AI.MIGRATION_REFERENCE (
    DOC_ID   TEXT,
    TITLE    TEXT,
    TOPIC    TEXT,
    DOC_TEXT TEXT
);

























